// Lemon Squeezy order_created webhook -> clean fields
const input = $input.first().json;
const body = input.body || input;
const meta = body.meta || {};
const data = body.data || {};
const attrs = data.attributes || {};
const item = attrs.first_order_item || {};
return [{
  json: {
    event: meta.event_name || body.event_name || '',
    order_id: String(data.id || ''),
    order_number: attrs.order_number || '',
    email: attrs.user_email || '',
    name: attrs.user_name || 'there',
    amount: attrs.total ? (attrs.total / 100).toFixed(2) : '0.00',
    currency: attrs.currency || 'GBP',
    product: item.product_name || 'Early Learners Printable Bundle',
    date: new Date().toISOString()
  }
}];

